INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-24', 'es', 'LAIKA 64 3.5.1: avatares animados y juegos reparados', '294 avatares animados, emojis animados en el chat, mensajes rápidos con X (también Discord y Telegram), lobby y salas renovados, lo más jugado en línea y logo animado. Reparados Pokémon Puzzle League (intro, tableros y cinemáticas) y Command & Conquer. Actualiza desde LAIKA.'),
 ('2026-11-24', 'en', 'LAIKA 64 3.5.1: animated avatars and fixed games', '294 animated avatars, animated emojis in chat, quick messages with X (Discord and Telegram too), a renewed lobby and rooms, the most played online and an animated logo. Fixed Pokémon Puzzle League (intro, boards and cutscenes) and Command & Conquer. Update from LAIKA.'),
 ('2026-11-24', 'pt', 'LAIKA 64 3.5.1: avatares animados e jogos corrigidos', '294 avatares animados, emojis animados no chat, mensagens rápidas com X (também Discord e Telegram), lobby e salas renovados, os mais jogados online e logo animado. Corrigidos Pokémon Puzzle League (intro, tabuleiros e cenas) e Command & Conquer. Atualize pelo LAIKA.'),
 ('2026-11-24', 'fr', 'LAIKA 64 3.5.1 : avatars animés et jeux corrigés', '294 avatars animés, émojis animés dans le chat, messages rapides avec X (Discord et Telegram aussi), salon et salles repensés, les plus joués en ligne et logo animé. Corrigés : Pokémon Puzzle League (intro, plateaux, cinématiques) et Command & Conquer. Mettez à jour depuis LAIKA.'),
 ('2026-11-24', 'it', 'LAIKA 64 3.5.1: avatar animati e giochi riparati', '294 avatar animati, emoji animate in chat, messaggi rapidi con X (anche Discord e Telegram), lobby e stanze rinnovate, i più giocati online e logo animato. Riparati Pokémon Puzzle League (intro, tabelloni e filmati) e Command & Conquer. Aggiorna da LAIKA.'),
 ('2026-11-24', 'de', 'LAIKA 64 3.5.1: animierte Avatare und reparierte Spiele', '294 animierte Avatare, animierte Emojis im Chat, Schnellnachrichten mit X (auch Discord und Telegram), erneuerte Lobby und Räume, meistgespielt online und ein animiertes Logo. Repariert: Pokémon Puzzle League (Intro, Spielfelder, Szenen) und Command & Conquer. Aktualisiere in LAIKA.'),
 ('2026-11-24', 'ru', 'LAIKA 64 3.5.1: анимированные аватары и исправленные игры', '294 анимированных аватара, анимированные эмодзи в чате, быстрые сообщения на X (и Discord, и Telegram), обновлённые лобби и комнаты, популярное онлайн и анимированный логотип. Исправлены Pokémon Puzzle League (интро, поля, ролики) и Command & Conquer. Обновитесь в LAIKA.');
